fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo (NOT the Ctrl+K search box) and choose the 'Dashboards' application; its 'Library' page opens (top nav: 'Library', 'Categories'). Get a dashboard you own: click the '+ New' button, choose 'Dashboard', type a name such as 'CU Toolbar Test' in the 'New dashboard' dialog and click 'Create' — the new dashboard opens in edit mode, so click 'Cancel' in its header to return to view mode (or instead open a dashboard you already own from the Library list). In view mode the toolbar at the top-right shows, left to right: a robot icon ('AI assistant' — do NOT use it), a star, a '+ Add to' dropdown, a share icon (three connected dots, tooltip 'Share dashboard') and a blue 'Edit' button. Then walk these actions IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) dashboard-share-dialog — click the share icon ('Share dashboard') and confirm a dialog titled 'Share \"<dashboard name>\"' opens with an 'Add people by name or email...' search box, a 'People with access' section whose first row is you marked 'Owner' (crown icon) — followed by 'Not shared with anyone yet' or by shared-person rows with view/edit/delete/share checkboxes — and 'Save' and 'Cancel' buttons; click 'Cancel' to close it; (2) dashboard-add-part — click 'Edit' to enter edit mode (an 'Editing' badge appears and the header shows 'Add part', 'Properties', 'Save' and 'Cancel'), then click 'Add part' (plus icon) and confirm a dialog titled 'Add a part' opens with a 'Part type' row of selectable tiles (such as View, Query, Artifact, Web page) or a 'No part types available' notice; click the dialog's 'Cancel', then click 'Cancel' in the dashboard header to leave edit mode; (3) dashboard-pin-to-home — back in view mode, click the '+ Add to' dropdown and confirm a menu opens with a 'HOME' heading, a 'Pin card' item ('A thumbnail card in Pinned') and a 'Share with people or roles…' item; click 'Pin card' and confirm a toast 'Pinned \"<dashboard name>\" to Home' (or '... is already pinned to Home') appears, then open '+ Add to' again and confirm the 'Pin card' item now shows a green '✓ Added' badge. Keep going until every action has been visited. You do NOT need to save the dashboard or add a part. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "dashboard-share-dialog",
      "instruction": "open the dashboard Share dialog",
      "visualCriteria": [
        "Clicking the 'Share dashboard' icon on an owned dashboard opens a dialog titled 'Share \"<dashboard name>\"' with an 'Add people by name or email...' search input, a 'People with access' section whose first row is the Owner, and Save/Cancel buttons (per-person view/edit/delete/share checkboxes appear only for people it is shared with; 'Not shared with anyone yet' is valid)"
      ]
    },
    {
      "name": "dashboard-add-part",
      "instruction": "open the Add a part dialog in edit mode",
      "visualCriteria": [
        "In dashboard edit mode (an 'Editing' badge with 'Add part', 'Properties', 'Save' and 'Cancel' in the header), clicking 'Add part' opens a dialog titled 'Add a part' showing a 'Part type' row of selectable tiles (such as View, Query, Artifact, Web page) or a 'No part types available' notice"
      ]
    },
    {
      "name": "dashboard-pin-to-home",
      "instruction": "pin the dashboard to Home from the Add to menu",
      "visualCriteria": [
        "In view mode, clicking '+ Add to' opens a menu with a 'HOME' heading, a 'Pin card' item and a 'Share with people or roles…' item; clicking 'Pin card' shows a 'Pinned \"<name>\" to Home' (or 'already pinned') toast, and reopening the menu shows the 'Pin card' item with a green '✓ Added' badge"
      ]
    }
  ]
}
